"""Time the blocking I/O a discovery tick runs, per call, against real repos.

Usage: .venv/bin/python scripts/explore/time_tick_io.py <repo-dir> [<repo-dir> ...]
"""

import sys
import time

from claude_dashboard.session import (
    detect_branch,
    discover_codex_sessions,
    discover_sessions,
    git_check,
    read_trunk_info,
)


def _timed(label: str, fn, *args, **kwargs):
    start = time.perf_counter()
    result = fn(*args, **kwargs)
    print(f"{(time.perf_counter() - start) * 1000:8.1f} ms  {label}")
    return result


def main() -> None:
    _timed("discover_sessions", discover_sessions)
    _timed("discover_codex_sessions", discover_codex_sessions)
    total = 0.0
    for cwd in sys.argv[1:]:
        _remote, trunk_ref, trunk_branch = read_trunk_info(cwd=cwd)
        branch = detect_branch(cwd=cwd, trunk_branch=trunk_branch)
        start = time.perf_counter()
        status = git_check(cwd=cwd, trunk_ref=trunk_ref, branch=branch)
        elapsed = (time.perf_counter() - start) * 1000
        total += elapsed
        print(f"{elapsed:8.1f} ms  git_check {cwd} branch={branch!r} -> {status}")
    print(f"{total:8.1f} ms  git_check total ({len(sys.argv) - 1} repos)")


if __name__ == "__main__":
    main()
